/* cppi::fe7d241af9a6b803eae0511daabb221179d73c9e160461a22500667d529863eb */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-18' and end_date = '2025-04-18')
and start_date = '2025-04-18' and end_date = '2025-04-18'

